const FAQ_HTML = '\n<header class="site-nav">\n  <div class="brand"><img class="brand-logo" src="data:image/png;base64," alt="">pagewright</div>\n    <nav><a href="/">Home</a><a href="/product">Product</a><a href="/pricing">Pricing</a><a href="/faq">FAQ</a><a href="/blog">Blog</a><a href="#" class="pill nav-login">Sign in</a><a class="pill nav-cta" href="/app">Get started</a></nav>\n</header>\n<main data-takyon-page="faq">\n<h1 class="page-title">Questions, answered plainly</h1>\n<div class="faq-list">\n  <details class="faq-item" open><summary class="faq-q">What is PageWright?</summary><div class="faq-a"><p>PageWright is a document generation platform. You design a document once — a quote, invoice, report, certificate, or contract — mark which parts change, and then produce unlimited personalised versions from a form, a spreadsheet, or your own software, without anyone reformatting a template by hand.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">How does it work?</summary><div class="faq-a"><p>You build a document in the visual editor from ready-made sections like headers, customer details, line-item tables, totals, terms, and signature blocks. You mark which parts are filled from data. From then on the document is generated automatically and comes back as a finished file ready to send.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">What kinds of documents can I create?</summary><div class="faq-a"><p>Anything your business sends to customers: quotes and estimates, invoices and statements, performance reports, training certificates, inspection and site reports, service agreements, and delivery notes or packing slips.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">Do I need a developer to use it?</summary><div class="faq-a"><p>No. It is built for the person who owns the document — an office manager or business owner — in a visual editor with no code required. Teams that want to automate it can use the generation API.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">How are totals and taxes handled?</summary><div class="faq-a"><p>Totals and taxes are calculated from the line items rather than typed in, so every quote and invoice comes out correctly priced without manual arithmetic.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">What happens when a document has more line items than fit on one page?</summary><div class="faq-a"><p>Documents grow and shrink to fit their contents. Line-item tables break across pages properly, column headers repeat, and running headers and footers keep page numbers correct — so a quote with four line items and one with two hundred both come out right.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">Can my own software generate documents?</summary><div class="faq-a"><p>Yes. The generation API accepts data from your own software with keys and webhooks, supports document merging, and returns the finished file ready to send.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">How do customers sign documents?</summary><div class="faq-a"><p>You can add fillable fields that customers sign on screen, then output the finished document as a PDF or image.</p></div></details>\n  <details class="faq-item"><summary class="faq-q">How do I sign in and manage my subscription?</summary><div class="faq-a"><p>Sign in is through Google, and your subscription is managed from your account profile.</p></div></details>\n</div>\n</main>\n<footer class="site-footer">\n  <!-- TAKYON:FOOTER-CTA:START -->\n  <section data-composition="full-width" data-intent="close" data-layout="close" data-footer-cta="true">\n  <div class="section-frame">\n    <h2 class="section-title">Send your first real document today</h2>\n    <p class="close-sub">Build a template, mark the fields that change, and generate a quote your customer can sign — in minutes, not half an hour.</p>\n    <a class="close-cta" data-focal="primary" href="#">Build your first template</a>\n  </div>\n</section>\n<!-- TAKYON:FOOTER-CTA:END -->\n  <div class="footer-inner">\n    <div class="footer-brand"><img class="brand-logo" src="data:image/png;base64," alt="">pagewright</div>\n    <nav aria-label="Footer"><a href="/">Home</a><a href="/product">Product</a><a href="/pricing">Pricing</a><a href="/faq">FAQ</a><a href="/blog">Blog</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></nav>\n  </div>\n</footer>\n';
const PRODUCT_HTML = '\n<header class="site-nav">\n  <div class="brand"><img class="brand-logo" src="data:image/png;base64," alt="">pagewright</div>\n    <nav><a href="/">Home</a><a href="/product">Product</a><a href="/pricing">Pricing</a><a href="/faq">FAQ</a><a href="/blog">Blog</a><a href="#" class="pill nav-login">Sign in</a><a class="pill nav-cta" href="/app">Get started</a></nav>\n</header>\n<main data-takyon-page="product">\n<h1 class="page-title">Paperwork that assembles itself — correctly, every time</h1>\n<div class="product-story">\n  <section class="product-block">\n    <h2>Build the document once</h2>\n    <p>Design any customer-facing document in the visual editor from ready-made sections — headers, customer details, line-item tables, totals, terms, and signature blocks — and mark which parts are filled from data. What you build becomes a reusable template, with a live preview so you can see the result as you work.</p>\n    <ul>\n      <li>Reusable templates you customise once and use forever</li>\n      <li>Sections that appear or disappear based on the data</li>\n      <li>Custom branding and themes so every document stays on brand</li>\n    </ul>\n  </section>\n  <section class="product-block">\n    <h2>Tables and totals that handle real documents</h2>\n    <p>PageWright is built for documents that change size, not fixed-size canvases. Line-item tables flow across pages with repeating column headers, and running headers and footers keep automatic page numbers in place however long the document gets.</p>\n    <ul>\n      <li>Tables that break across pages cleanly</li>\n      <li>Totals and taxes calculated from the line items</li>\n      <li>Documents that grow and shrink to fit their contents</li>\n    </ul>\n  </section>\n  <section class="product-block">\n    <h2>Generate from a form, a spreadsheet, or your software</h2>\n    <p>Once the template exists, generating is automatic. Staff enter the details, a spreadsheet is uploaded, or your own software sends the data — and PageWright returns the finished file ready to send.</p>\n    <ul>\n      <li>Form entry for the team that does it by hand</li>\n      <li>Spreadsheet upload for bulk runs</li>\n      <li>Generation API with keys and webhooks for automation</li>\n      <li>Document merging for multi-source output</li>\n    </ul>\n  </section>\n  <section class="product-block">\n    <h2>Brand it and collect signatures on screen</h2>\n    <p>Apply your own branding and themes, then add fillable fields customers can sign on screen. The finished document exports to PDF or image, ready to send.</p>\n    <ul>\n      <li>Fillable fields customers sign on screen</li>\n      <li>PDF and image output</li>\n      <li>A clean, consistently branded result every time</li>\n    </ul>\n  </section>\n  <section class="product-block">\n    <h2>Keep every version under control</h2>\n    <p>Every document produced is recorded, so you have a clear history of what was sent and when — the paperwork trail is built in, not bolted on.</p>\n    <ul>\n      <li>Full history of every document produced</li>\n    </ul>\n  </section>\n</div>\n</main>\n<footer class="site-footer">\n  <!-- TAKYON:FOOTER-CTA:START -->\n  <section data-composition="full-width" data-intent="close" data-layout="close" data-footer-cta="true">\n  <div class="section-frame">\n    <h2 class="section-title">Send your first real document today</h2>\n    <p class="close-sub">Build a template, mark the fields that change, and generate a quote your customer can sign — in minutes, not half an hour.</p>\n    <a class="close-cta" data-focal="primary" href="#">Build your first template</a>\n  </div>\n</section>\n<!-- TAKYON:FOOTER-CTA:END -->\n  <div class="footer-inner">\n    <div class="footer-brand"><img class="brand-logo" src="data:image/png;base64," alt="">pagewright</div>\n    <nav aria-label="Footer"><a href="/">Home</a><a href="/product">Product</a><a href="/pricing">Pricing</a><a href="/faq">FAQ</a><a href="/blog">Blog</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></nav>\n  </div>\n</footer>\n';
const PRIVACY_HTML = '\n<header class="site-nav">\n  <div class="brand"><img class="brand-logo" src="data:image/png;base64," alt="">pagewright</div>\n    <nav><a href="/">Home</a><a href="/product">Product</a><a href="/pricing">Pricing</a><a href="/faq">FAQ</a><a href="/blog">Blog</a><a href="#" class="pill nav-login">Sign in</a><a class="pill nav-cta" href="/app">Get started</a></nav>\n</header>\n<main data-takyon-page="privacy">\n<h1 class="page-title">Privacy</h1>\n<section>\n  <h2>What we store</h2>\n  <p>pagewright stores the account, product records, and usage receipts needed to\n  provide the service: account identity, subscription state, profile details, and the\n  content you create inside the product.</p>\n</section>\n<section>\n  <h2>How we use it</h2>\n  <p>We use this data to sign you in, manage access, process billing events, and deliver\n  the features you request. We do not sell your data.</p>\n</section>\n<section>\n  <h2>Sign-in and billing</h2>\n  <p>Sign-in uses your Google account. Subscription billing and payment events are handled\n  by secure payment processors; pagewright never stores your card details.</p>\n</section>\n<section>\n  <h2>Contact</h2>\n  <p>Questions about this policy are answered through the support channel inside the\n  product.</p>\n</section>\n</main>\n<footer class="site-footer">\n  <!-- TAKYON:FOOTER-CTA:START -->\n  <section data-composition="full-width" data-intent="close" data-layout="close" data-footer-cta="true">\n  <div class="section-frame">\n    <h2 class="section-title">Send your first real document today</h2>\n    <p class="close-sub">Build a template, mark the fields that change, and generate a quote your customer can sign — in minutes, not half an hour.</p>\n    <a class="close-cta" data-focal="primary" href="#">Build your first template</a>\n  </div>\n</section>\n<!-- TAKYON:FOOTER-CTA:END -->\n  <div class="footer-inner">\n    <div class="footer-brand"><img class="brand-logo" src="data:image/png;base64," alt="">pagewright</div>\n    <nav aria-label="Footer"><a href="/">Home</a><a href="/product">Product</a><a href="/pricing">Pricing</a><a href="/faq">FAQ</a><a href="/blog">Blog</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></nav>\n  </div>\n</footer>\n';
